	/** 
	 * jumpstart the process by instantiating2 Transaction
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		transactionId = TransactionService.getTransactionInstance()
		.createTransaction( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		TransactionService.getTransactionInstance()
				.createTransaction( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.transactionSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Transaction : " + successValue.getTransactionId());
							  if (successValue.getTransactionId().equals(transactionId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfTransactionList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Transaction test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on transaction consumed")
					);
			subscriber.transactionSubscribe( transactionId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Transaction : " + successValue.getTransactionId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfTransactionList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on transaction for transactionId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Transaction. 
	 */
	protected Transaction read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Transaction" );

		Transaction entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Transaction with primary key" );
		msg.append( transactionId );
		
		TransactionFetchOneSummary fetchOneSummary = new TransactionFetchOneSummary( transactionId );

		try {
			entity = TransactionService.getTransactionInstance().getTransaction( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Transaction " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Transaction.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Transaction." );

		StringBuilder msg = new StringBuilder( "Failed to update a Transaction : " );        
		Transaction entity = read();
		UpdateTransactionCommand command = generateUpdateCommand();
		command.setTransactionId(entity.getTransactionId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Transaction." );

			// for use later on...
			transactionId = entity.getTransactionId();

			TransactionService proxy = TransactionService.getTransactionInstance();  

			proxy.updateTransaction( command ).get();

			LOGGER.info( "-- Successfully saved Transaction - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + transactionId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Transaction.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Transaction." );

		Transaction entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Transaction with id " + transactionId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Transaction with id " + transactionId );

			throw e;
		}

		try{
			TransactionService.getTransactionInstance().delete( new DeleteTransactionCommand( entity.getTransactionId() ) ).get();
			LOGGER.info( "-- Successfully deleted Transaction with id " + transactionId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Transaction with id " + transactionId );

			throw e;
		}
	}

	/**
	 * get all Transactions.
	 */
	protected List<Transaction> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Transactions:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Transaction : " );        
		List<Transaction> collection  = new ArrayList<>();

		try {
			// call the static get method on the TransactionService
			collection = TransactionService.getTransactionInstance().getAllTransaction();
			assertNotNull( collection, "An Empty collection of Transaction was incorrectly returned.");
			
			// Now print out the values
			Transaction entity = null;            
			Iterator<Transaction> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getTransactionId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

